1	import { Queue } from 'bullmq'
2	import IORedis from 'ioredis'
3	
4	/**
5	 * BullMQ job queue enqueuer for the web service.
6	 *
7	 * The web service ONLY enqueues jobs — it never processes them.
8	 * Jobs are processed by the worker-jobs Railway service.
9	 *
10	 * Uses REDIS_PRIVATE_URL (Railway internal DNS) in production.
11	 */
12	
13	let _connection: IORedis | null = null
14	
15	function getConnection(): IORedis {
16	  if (!_connection) {
17	    const redisUrl = process.env.REDIS_PRIVATE_URL
18	    if (!redisUrl) {
19	      throw new Error('REDIS_PRIVATE_URL is not configured')
20	    }
21	    _connection = new IORedis(redisUrl, {
22	      // REQUIRED: BullMQ requires maxRetriesPerRequest to be null
23	      maxRetriesPerRequest: null,
24	      enableReadyCheck: false,
25	      lazyConnect: true,
26	    })
27	  }
28	  return _connection
29	}
30	
31	let _queue: Queue | null = null
32	
33	function getQueue(): Queue {
34	  if (!_queue) {
35	    _queue = new Queue('inkos-jobs', {
36	      connection: getConnection(),
37	      defaultJobOptions: {
38	        attempts: 3,
39	        backoff: {
40	          type: 'exponential',
41	          delay: 2000,
42	        },
43	        removeOnComplete: { count: 1000, age: 86400 },
44	        removeOnFail: { count: 5000 },
45	      },
46	    })
47	  }
48	  return _queue
49	}
50	
51	/**
52	 * Job payload type map — add new job types here as sprints add features.
53	 */
54	export interface JobPayloads {
55	  'send-email': {
56	    to: string
57	    template: string
58	    data: Record<string, unknown>
59	  }
60	  'generate-consent-pdf': {
61	    submission_id: string
62	    studio_id: string
63	  }
64	  'process-ai-design': {
65	    requestId: string
66	    studioId: string
67	  }
68	  'send-booking-reminder': {
69	    bookingId: string
70	    reminderType: 'day_before' | 'hour_before'
71	  }
72	  'generate-payroll': {
73	    studioId: string
74	    periodStart: string
75	    periodEnd: string
76	  }
77	  'sync-calendar': {
78	    studioId: string
79	    artistId: string
80	  }
81	  'generate-1099k': {
82	    studioId: string
83	    artistId: string
84	    year: number
85	  }
86	  'generate-tax-form-pdf': {
87	    form_id: string
88	    studio_id: string
89	  }
90	  'send-tax-form': {
91	    form_id: string
92	    studio_id: string
93	    sent_by: string
94	  }
95	}
96	
97	/**
98	 * Type-safe job enqueue helper.
99	 */
100	export async function enqueueJob<K extends keyof JobPayloads>(
101	  name: K,
102	  data: JobPayloads[K],
103	  options?: { delay?: number; priority?: number }
104	): Promise<string | undefined> {
105	  const job = await getQueue().add(name, data, options)
106	  return job.id
107	}
108

