/**
 * Per-model token → cost calculation.
 *
 * Rates as of 2026-04. Override per-env when provider pricing changes.
 * All costs in integer cents to avoid floating-point drift.
 */

export interface TokenCost {
  inputCents: number
  outputCents: number
  totalCents: number
}

/** Claude Sonnet input: $3/MTok, output: $15/MTok */
const CLAUDE_SONNET_INPUT_CENTS_PER_MTOK = 300   // $3.00 per million tokens
const CLAUDE_SONNET_OUTPUT_CENTS_PER_MTOK = 1500  // $15.00 per million tokens

/** DALL-E 3 HD 1024×1024: $0.08/image */
export const DALLE3_HD_COST_CENTS = 8

/** Stability SDXL: ~$0.03/image */
export const STABILITY_SDXL_COST_CENTS = 3

export function claudeSonnetCost(tokensInput: number, tokensOutput: number): TokenCost {
  const inputCents = Math.ceil((tokensInput / 1_000_000) * CLAUDE_SONNET_INPUT_CENTS_PER_MTOK)
  const outputCents = Math.ceil((tokensOutput / 1_000_000) * CLAUDE_SONNET_OUTPUT_CENTS_PER_MTOK)
  return { inputCents, outputCents, totalCents: inputCents + outputCents }
}

export function imageGenCost(provider: 'openai' | 'stability'): number {
  return provider === 'openai' ? DALLE3_HD_COST_CENTS : STABILITY_SDXL_COST_CENTS
}

