/**
 * GET  /api/ai/requests   — gallery list via get_ai_design_gallery RPC
 * POST /api/ai/requests   — create new design request via create_ai_design_request RPC
 */

import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { expensiveRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { enqueueJob } from '@/lib/queue'
import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'

const STYLE_CATEGORIES = [
  'blackwork', 'watercolor', 'traditional', 'neo_trad', 'realism',
  'geometric', 'minimalist', 'japanese', 'tribal', 'trash_polka',
  'dotwork', 'illustrative', 'abstract', 'lettering', 'other',
] as const

const CreateRequestSchema = z.object({
  studio_id: z.string().uuid(),
  style_category: z.enum(STYLE_CATEGORIES),
  description: z.string().min(1).max(2000),
  client_id: z.string().uuid().optional(),
  booking_id: z.string().uuid().optional(),
  artist_id: z.string().uuid().optional(),
  body_area: z.string().max(100).optional(),
  size_estimate: z.enum(['small', 'medium', 'large', 'sleeve', 'half-sleeve', 'full-back', 'quarter-sleeve']).optional(),
  budget_min_cents: z.number().int().positive().optional(),
  budget_max_cents: z.number().int().positive().optional(),
  reference_image_urls: z.array(z.string().url()).max(5).optional(),
  mood_keywords: z.array(z.string().max(50)).max(20).optional(),
  avoid_keywords: z.array(z.string().max(50)).max(20).optional(),
  notes: z.string().max(1000).optional(),
  priority: z.number().int().min(0).max(10).optional(),
})

const GalleryFiltersSchema = z.object({
  style: z.string().optional(),
  artist_id: z.string().uuid().optional(),
  client_id: z.string().uuid().optional(),
  status: z.string().optional(),
  from_date: z.string().optional(),
  to_date: z.string().optional(),
  limit: z.coerce.number().int().min(1).max(200).default(50),
  offset: z.coerce.number().int().min(0).default(0),
})

export async function GET(req: NextRequest) {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { searchParams } = new URL(req.url)
  const studioId = searchParams.get('studio_id')
  if (!studioId) return Response.json({ error: 'studio_id required' }, { status: 400 })

  const filtersRaw: Record<string, string> = {}
  for (const [k, v] of searchParams.entries()) {
    if (k !== 'studio_id') filtersRaw[k] = v
  }
  const parsedFilters = GalleryFiltersSchema.safeParse(filtersRaw)
  if (!parsedFilters.success) {
    return Response.json({ error: parsedFilters.error.flatten() }, { status: 400 })
  }

  try {
    const { data, error } = await supabase.rpc('get_ai_design_gallery', {
      p_studio_id: studioId,
      p_filters: parsedFilters.data,
    })
    if (error) throw error
    return Response.json({ data })
  } catch (err) {
    logger.error({ err, studioId }, 'get_ai_design_gallery failed')
    return Response.json({ error: 'Failed to load gallery' }, { status: 500 })
  }
}

export async function POST(req: NextRequest) {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  // Rate limit: 5/min per user (expensiveRatelimit)
  const ip = getClientIp(req)
  const rl = await expensiveRatelimit.limit(`ai:req:${user.id}:${ip}`)
  if (!rl.success) {
    return Response.json(
      { error: 'Rate limit exceeded. Maximum 5 AI requests per minute.' },
      { status: 429, headers: { 'Retry-After': String(Math.ceil((rl.reset - Date.now()) / 1000)) } },
    )
  }

  const body = CreateRequestSchema.safeParse(await req.json())
  if (!body.success) {
    return Response.json({ error: body.error.flatten() }, { status: 400 })
  }

  const { studio_id, ...requestData } = body.data

  // Feature gate — Pro+ only (server-enforced)
  try {
    await requireFeatureRpc(supabase, studio_id, 'ai_design_assistant')
  } catch (e) {
    if (e instanceof FeatureGateError) {
      return Response.json(
        { error: 'AI Design Assistant requires Pro plan or higher', requiredPlan: 'pro' },
        { status: 403 },
      )
    }
    throw e
  }

  // Create request via RPC (handles feature gate + usage metering in DB)
  let requestId: string
  try {
    const { data, error } = await supabase.rpc('create_ai_design_request', {
      p_studio_id: studio_id,
      p_data: requestData,
    })
    if (error) {
      if (error.message.includes('feature_not_available')) {
        return Response.json({ error: 'AI Design Assistant not available on current plan', requiredPlan: 'pro' }, { status: 403 })
      }
      if (error.message.includes('quota_exceeded')) {
        return Response.json({ error: 'Monthly AI generation quota exceeded' }, { status: 429 })
      }
      throw error
    }
    requestId = data as string
  } catch (err) {
    logger.error({ err, studio_id }, 'create_ai_design_request RPC failed')
    return Response.json({ error: 'Failed to create design request' }, { status: 500 })
  }

  // Enqueue worker job — AI processing never runs on web service
  try {
    await enqueueJob('process-ai-design', { requestId, studioId: studio_id })
  } catch (err) {
    logger.error({ err, requestId }, 'failed to enqueue process-ai-design job')
    // Request is created — don't fail the response, worker retry will pick it up
  }

  return Response.json({ data: { id: requestId } }, { status: 201 })
}

/**
 * GET   /api/ai/requests/[id]  — request detail with outputs
 * PATCH /api/ai/requests/[id]  — cancel request
 */

import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

const PatchSchema = z.object({
  action: z.literal('cancel'),
})

export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: request, error } = await supabase
    .from('ai_design_requests')
    .select('*')
    .eq('id', id)
    .single()

  if (error || !request) {
    return Response.json({ error: 'Request not found' }, { status: 404 })
  }

  const { data: outputs, error: outputsErr } = await supabase
    .from('ai_design_outputs')
    .select('*')
    .eq('request_id', id)
    .order('sequence', { ascending: true })

  if (outputsErr) {
    logger.error({ err: outputsErr, requestId: id }, 'failed to fetch outputs')
  }

  return Response.json({ data: { request, outputs: outputs ?? [] } })
}

export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const body = PatchSchema.safeParse(await req.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  // Verify ownership via RLS
  const { data: request } = await supabase
    .from('ai_design_requests')
    .select('id, status')
    .eq('id', id)
    .single()

  if (!request) return Response.json({ error: 'Request not found' }, { status: 404 })
  if (request.status === 'completed' || request.status === 'cancelled') {
    return Response.json({ error: `Cannot cancel a ${request.status} request` }, { status: 422 })
  }

  const { error } = await supabase
    .from('ai_design_requests')
    .update({ status: 'cancelled' })
    .eq('id', id)

  if (error) {
    logger.error({ err: error, id }, 'failed to cancel ai_design_request')
    return Response.json({ error: 'Failed to cancel request' }, { status: 500 })
  }

  return Response.json({ data: { id, status: 'cancelled' } })
}

/**
 * POST /api/ai/requests/[id]/regenerate
 * Enqueues another AI processing run for an existing request (new iteration).
 */

import { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { expensiveRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { enqueueJob } from '@/lib/queue'
import { logger } from '@/lib/logger'

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const ip = getClientIp(req)
  const rl = await expensiveRatelimit.limit(`ai:regen:${user.id}:${ip}`)
  if (!rl.success) {
    return Response.json(
      { error: 'Rate limit exceeded. Maximum 5 AI requests per minute.' },
      { status: 429, headers: { 'Retry-After': String(Math.ceil((rl.reset - Date.now()) / 1000)) } },
    )
  }

  // Verify request exists and belongs to user's studio (RLS enforces)
  const { data: request } = await supabase
    .from('ai_design_requests')
    .select('id, studio_id, status')
    .eq('id', id)
    .single()

  if (!request) return Response.json({ error: 'Request not found' }, { status: 404 })
  if (request.status === 'processing') {
    return Response.json({ error: 'Request is already being processed' }, { status: 422 })
  }

  // Reset to pending for the new run
  await supabase
    .from('ai_design_requests')
    .update({ status: 'pending', failure_reason: null })
    .eq('id', id)

  try {
    await enqueueJob('process-ai-design', { requestId: id, studioId: request.studio_id })
  } catch (err) {
    logger.error({ err, id }, 'failed to enqueue process-ai-design regenerate job')
    return Response.json({ error: 'Failed to enqueue regeneration' }, { status: 500 })
  }

  return Response.json({ data: { id, status: 'pending' } })
}

/**
 * PATCH /api/ai/outputs/[id]
 * Update output: rate, approve, reject, or save artist notes.
 */

import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

const PatchSchema = z.discriminatedUnion('action', [
  z.object({
    action: z.literal('rate'),
    rating: z.number().int().min(1).max(5),
  }),
  z.object({
    action: z.literal('notes'),
    artist_notes: z.string().max(2000),
  }),
  z.object({
    action: z.literal('approve'),
  }),
  z.object({
    action: z.literal('reject'),
  }),
])

export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const body = PatchSchema.safeParse(await req.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  // Verify output exists (RLS ensures studio scope)
  const { data: output } = await supabase
    .from('ai_design_outputs')
    .select('id, studio_id, status')
    .eq('id', id)
    .single()

  if (!output) return Response.json({ error: 'Output not found' }, { status: 404 })

  let updatePayload: Record<string, unknown> = {}
  let auditAction = ''

  switch (body.data.action) {
    case 'rate':
      updatePayload = { rating: body.data.rating }
      auditAction = 'ai_output.rated'
      break
    case 'notes':
      updatePayload = { artist_notes: body.data.artist_notes }
      auditAction = 'ai_output.notes_saved'
      break
    case 'approve':
      updatePayload = { status: 'approved', approved_at: new Date().toISOString(), approved_by: user.id }
      auditAction = 'ai_output.approved'
      break
    case 'reject':
      updatePayload = { status: 'rejected' }
      auditAction = 'ai_output.rejected'
      break
  }

  const { error } = await supabase
    .from('ai_design_outputs')
    .update(updatePayload)
    .eq('id', id)

  if (error) {
    logger.error({ err: error, id, action: body.data.action }, 'ai output update failed')
    return Response.json({ error: 'Failed to update output' }, { status: 500 })
  }

  await logAuditAction(supabase, {
    studioId: output.studio_id,
    actorId: user.id,
    action: auditAction,
    targetType: 'ai_design_output',
    targetId: id,
    details: body.data,
  })

  return Response.json({ data: { id, ...updatePayload } })
}

/**
 * PATCH /api/ai/outputs/[id]
 * Update output: rate, approve, reject, or save artist notes.
 */

import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

const PatchSchema = z.discriminatedUnion('action', [
  z.object({
    action: z.literal('rate'),
    rating: z.number().int().min(1).max(5),
  }),
  z.object({
    action: z.literal('notes'),
    artist_notes: z.string().max(2000),
  }),
  z.object({
    action: z.literal('approve'),
  }),
  z.object({
    action: z.literal('reject'),
  }),
])

export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const body = PatchSchema.safeParse(await req.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  // Verify output exists (RLS ensures studio scope)
  const { data: output } = await supabase
    .from('ai_design_outputs')
    .select('id, studio_id, status')
    .eq('id', id)
    .single()

  if (!output) return Response.json({ error: 'Output not found' }, { status: 404 })

  let updatePayload: Record<string, unknown> = {}
  let auditAction = ''

  switch (body.data.action) {
    case 'rate':
      updatePayload = { rating: body.data.rating }
      auditAction = 'ai_output.rated'
      break
    case 'notes':
      updatePayload = { artist_notes: body.data.artist_notes }
      auditAction = 'ai_output.notes_saved'
      break
    case 'approve':
      updatePayload = { status: 'approved', approved_at: new Date().toISOString(), approved_by: user.id }
      auditAction = 'ai_output.approved'
      break
    case 'reject':
      updatePayload = { status: 'rejected' }
      auditAction = 'ai_output.rejected'
      break
  }

  const { error } = await supabase
    .from('ai_design_outputs')
    .update(updatePayload)
    .eq('id', id)

  if (error) {
    logger.error({ err: error, id, action: body.data.action }, 'ai output update failed')
    return Response.json({ error: 'Failed to update output' }, { status: 500 })
  }

  await logAuditAction(
    user.id,
    auditAction,
    { type: 'ai_design_output', id },
    body.data,
    output.studio_id,
  )

  return Response.json({ data: { id, ...updatePayload } })
}

/**
 * POST /api/ai/outputs/[id]/share
 * Calls share_output_with_client RPC → returns signed URL for client sharing.
 */

import { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

export async function POST(
  _req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  // Verify output exists and has an image
  const { data: output } = await supabase
    .from('ai_design_outputs')
    .select('id, studio_id, image_url, status')
    .eq('id', id)
    .single()

  if (!output) return Response.json({ error: 'Output not found' }, { status: 404 })
  if (!output.image_url) return Response.json({ error: 'Output has no image to share' }, { status: 422 })

  // Call RPC to get storage path token
  let token: string
  try {
    const { data, error } = await supabase.rpc('share_output_with_client', { p_output_id: id })
    if (error) throw error
    token = data as string
  } catch (err) {
    logger.error({ err, id }, 'share_output_with_client RPC failed')
    return Response.json({ error: 'Failed to generate share token' }, { status: 500 })
  }

  // Create a 1-hour signed URL from service-role client
  const serviceSupabase = createServiceRoleClient()
  const storagePath = output.image_url.replace(/^.*design-assets\//, '')

  const { data: signedData, error: signedError } = await serviceSupabase
    .storage
    .from('design-assets')
    .createSignedUrl(storagePath, 3600) // 1 hour

  if (signedError || !signedData) {
    logger.error({ err: signedError, storagePath }, 'failed to create signed URL')
    return Response.json({ error: 'Failed to generate signed image URL' }, { status: 500 })
  }

  // Mark output as shared
  await supabase
    .from('ai_design_outputs')
    .update({ shared_with_client: true, shared_at: new Date().toISOString() })
    .eq('id', id)

  await logAuditAction(
    user.id,
    'ai_output.shared_with_client',
    { type: 'ai_design_output', id },
    { token },
    output.studio_id,
  )

  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? 'http://localhost:3100'
  const sharePageUrl = `${appUrl}/ai-design/shared/${encodeURIComponent(token)}`

  return Response.json({
    data: {
      token,
      signedImageUrl: signedData.signedUrl,
      sharePageUrl,
    },
  })
}

/**
