/**
 * GET    /api/ai/templates/[id]  — fetch single template
 * PATCH  /api/ai/templates/[id]  — update studio-custom template
 * DELETE /api/ai/templates/[id]  — deactivate studio-custom template
 */

import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

const PatchSchema = z.object({
  name: z.string().min(1).max(100).optional(),
  system_prompt: z.string().min(1).max(8000).optional(),
  user_prompt_template: z.string().min(1).max(4000).optional(),
  image_prompt_template: z.string().max(2000).nullish(),
  is_active: z.boolean().optional(),
  is_default: z.boolean().optional(),
})

async function resolveTemplate(supabase: Awaited<ReturnType<typeof createClient>>, id: string, userId: string) {
  const { data: template } = await supabase
    .from('ai_design_templates')
    .select('id, studio_id, is_active')
    .eq('id', id)
    .single()

  if (!template) return { template: null, member: null }

  // Global templates: not editable via API
  if (!template.studio_id) return { template, member: null, isGlobal: true }

  const { data: member } = await supabase
    .from('studio_members')
    .select('role')
    .eq('studio_id', template.studio_id)
    .eq('user_id', userId)
    .single()

  return { template, member, isGlobal: false }
}

export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data, error } = await supabase
    .from('ai_design_templates')
    .select('*')
    .eq('id', id)
    .single()

  if (error || !data) return Response.json({ error: 'Template not found' }, { status: 404 })
  return Response.json({ data })
}

export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const body = PatchSchema.safeParse(await req.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  const { template, member, isGlobal } = await resolveTemplate(supabase, id, user.id)
  if (!template) return Response.json({ error: 'Template not found' }, { status: 404 })
  if (isGlobal) return Response.json({ error: 'System templates are read-only' }, { status: 403 })
  if (!member || !['owner', 'admin'].includes(member.role)) {
    return Response.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { data, error } = await supabase
    .from('ai_design_templates')
    .update(body.data)
    .eq('id', id)
    .select()
    .single()

  if (error) {
    logger.error({ err: error, id }, 'failed to update ai_design_template')
    return Response.json({ error: 'Failed to update template' }, { status: 500 })
  }

  return Response.json({ data })
}

export async function DELETE(
  _req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { template, member, isGlobal } = await resolveTemplate(supabase, id, user.id)
  if (!template) return Response.json({ error: 'Template not found' }, { status: 404 })
  if (isGlobal) return Response.json({ error: 'System templates cannot be deleted' }, { status: 403 })
  if (!member || !['owner', 'admin'].includes(member.role)) {
    return Response.json({ error: 'Forbidden' }, { status: 403 })
  }

  // Soft-delete: set is_active = false
  const { error } = await supabase
    .from('ai_design_templates')
    .update({ is_active: false })
    .eq('id', id)

  if (error) {
    logger.error({ err: error, id }, 'failed to deactivate ai_design_template')
    return Response.json({ error: 'Failed to delete template' }, { status: 500 })
  }

  return new Response(null, { status: 204 })
}

