/**
 * GET /api/public/ai/shared/[token]
 * Public (no auth) — returns shared output data for the client share page.
 * The token format is "{studio_slug}/{output_id}" as returned by share_output_with_client RPC.
 */

import { NextRequest } from 'next/server'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ token: string }> },
) {
  const { token } = await params
  const decoded = decodeURIComponent(token)

  // Token format: "{studio_slug}/{output_id}"
  const parts = decoded.split('/')
  if (parts.length < 2) {
    return Response.json({ error: 'Invalid share token' }, { status: 400 })
  }

  const outputId = parts[parts.length - 1]
  const studioSlug = parts.slice(0, -1).join('/')

  if (!outputId.match(/^[0-9a-f-]{36}$/)) {
    return Response.json({ error: 'Invalid share token' }, { status: 400 })
  }

  const supabase = createServiceRoleClient()

  // Fetch output + request + studio info
  const { data: output, error: outputErr } = await supabase
    .from('ai_design_outputs')
    .select(`
      id, response_text, image_url, status, model, rating, artist_notes,
      shared_with_client, shared_at, created_at,
      request:ai_design_requests (
        id, style_category, body_area, description, mood_keywords,
        studio:studios (id, name, slug, logo_url, brand_color)
      )
    `)
    .eq('id', outputId)
    .eq('shared_with_client', true)
    .single()

  if (outputErr || !output) {
    logger.error({ err: outputErr, outputId }, 'public share: output not found')
    return Response.json({ error: 'Design not found or share link expired' }, { status: 404 })
  }

  // Verify studio slug matches (security: prevent output ID enumeration across studios)
  type RequestWithStudio = typeof output.request & { studio?: { slug?: string } | null }
  const request = output.request as RequestWithStudio
  if (request?.studio && 'slug' in request.studio && request.studio.slug !== studioSlug) {
    return Response.json({ error: 'Design not found or share link expired' }, { status: 404 })
  }

  // Create a short-lived signed URL for the image if it exists
  let signedImageUrl: string | null = null
  if (output.image_url) {
    const storagePath = output.image_url.replace(/^.*design-assets\//, '')
    const { data: signed } = await supabase
      .storage
      .from('design-assets')
      .createSignedUrl(storagePath, 3600)
    signedImageUrl = signed?.signedUrl ?? null
  }

  return Response.json({
    data: {
      id: output.id,
      response_text: output.response_text,
      image_url: signedImageUrl,
      status: output.status,
      created_at: output.created_at,
      request: {
        id: request?.id,
        style_category: request?.style_category,
        body_area: request?.body_area,
        description: request?.description,
        mood_keywords: request?.mood_keywords,
      },
      studio: request?.studio ?? null,
    },
  })
}

/**
 * process-ai-design job handler.
 *
 * Pipeline:
 *   Step 1: Claude text analysis — moodboard description + composition + palette
 *   Step 2: Image generation via DALL-E 3 (or Stability AI)
 *   Step 3: AI usage logging to ai_usage_log
 *
 * WORKER-ONLY. Never import next/* here.
 * Uses service-role Supabase client (bypasses RLS).
 */

import { createClient } from '@supabase/supabase-js'
import Anthropic from '@anthropic-ai/sdk'
import OpenAI from 'openai'
import pino from 'pino'

const logger = pino({ level: process.env['LOG_LEVEL'] ?? 'info' })

// ---------------------------------------------------------------------------
// Supabase service-role client (worker scope)
// ---------------------------------------------------------------------------

function getServiceRoleClient() {
  const url = process.env['NEXT_PUBLIC_SUPABASE_URL'] ?? process.env['SUPABASE_URL']
  const key = process.env['SUPABASE_SERVICE_ROLE_KEY']
  if (!url || !key) throw new Error('Missing Supabase env vars for process-ai-design worker')
  return createClient(url, key, {
    auth: { autoRefreshToken: false, persistSession: false },
  })
}

// ---------------------------------------------------------------------------
// Cost calculation (matches lib/ai/cost-calculator.ts — duplicated here to
// avoid importing from Next.js web package)
// ---------------------------------------------------------------------------

const CLAUDE_INPUT_CENTS_PER_MTOK = 300
const CLAUDE_OUTPUT_CENTS_PER_MTOK = 1500
const DALLE3_HD_COST_CENTS = 8

function claudeCostCents(inputTokens: number, outputTokens: number): number {
  const input = Math.ceil((inputTokens / 1_000_000) * CLAUDE_INPUT_CENTS_PER_MTOK)
  const output = Math.ceil((outputTokens / 1_000_000) * CLAUDE_OUTPUT_CENTS_PER_MTOK)
  return input + output
}

// ---------------------------------------------------------------------------
// Prompt hydration (mirrors lib/ai/design-prompt-chain.ts)
// ---------------------------------------------------------------------------

function hydratePrompt(template: string, ctx: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (_, key: string) => ctx[key] ?? '')
}

function buildImagePrompt(moodboard: string, style: string, bodyArea?: string | null): string {
  const placement = bodyArea ? ` designed for placement on the ${bodyArea}` : ''
  return (
    `A high-quality tattoo design in ${style} style${placement}. ` +
    `${moodboard} ` +
    `Professional tattoo flash art, clean lines, black outlines, suitable for tattooing. ` +
    `Black background, centered composition, no text labels, no watermarks.`
  )
}

// ---------------------------------------------------------------------------
// DB types (minimal — avoid importing full types package)
// ---------------------------------------------------------------------------

interface AiDesignRequestRow {
  id: string
  studio_id: string
  style_category: string
  description: string
  body_area: string | null
  size_estimate: string | null
  mood_keywords: string[] | null
  avoid_keywords: string[] | null
  budget_min_cents: number | null
  budget_max_cents: number | null
  reference_image_urls: string[] | null
  notes: string | null
  status: string
}

interface AiDesignTemplateRow {
  id: string
  system_prompt: string
  user_prompt_template: string
  image_prompt_template: string | null
}

// ---------------------------------------------------------------------------
// Handler
// ---------------------------------------------------------------------------

export interface ProcessAiDesignJobData {
  requestId: string
  studioId: string
}

export async function handleProcessAiDesign({ requestId, studioId }: ProcessAiDesignJobData): Promise<void> {
  const log = logger.child({ handler: 'process-ai-design', requestId, studioId })
  log.info('starting AI design pipeline')

  const supabase = getServiceRoleClient()

  // --- Fetch request row ---
  const { data: request, error: reqErr } = await supabase
    .from('ai_design_requests')
    .select('*')
    .eq('id', requestId)
    .single()

  if (reqErr || !request) {
    log.error({ err: reqErr }, 'request not found')
    throw new Error(`ai_design_request not found: ${requestId}`)
  }

  const req = request as unknown as AiDesignRequestRow

  if (req.status === 'cancelled') {
    log.info('request was cancelled — skipping')
    return
  }

  // Mark as processing
  await supabase
    .from('ai_design_requests')
    .update({ status: 'processing', processing_started_at: new Date().toISOString() })
    .eq('id', requestId)

  // Count existing outputs for sequence numbering
  const { count: existingCount } = await supabase
    .from('ai_design_outputs')
    .select('id', { count: 'exact', head: true })
    .eq('request_id', requestId)

  let nextSequence = (existingCount ?? 0) + 1

  try {
    // --- Step 1: Fetch best matching prompt template ---
    const { data: templates } = await supabase
      .from('ai_design_templates')
      .select('id, system_prompt, user_prompt_template, image_prompt_template')
      .or(`studio_id.eq.${studioId},studio_id.is.null`)
      .eq('style_category', req.style_category)
      .eq('is_active', true)
      .order('studio_id', { ascending: false, nullsFirst: false }) // studio custom first
      .limit(1)

    const template = templates?.[0] as AiDesignTemplateRow | undefined

    if (!template) {
      throw new Error(`No active template found for style: ${req.style_category}`)
    }

    // --- Step 2: Anthropic Claude analysis ---
    const anthropicKey = process.env['ANTHROPIC_API_KEY']
    if (!anthropicKey) throw new Error('ANTHROPIC_API_KEY not configured')

    const anthropic = new Anthropic({ apiKey: anthropicKey })

    const ctx: Record<string, string> = {
      description: req.description,
      style: req.style_category,
      body_area: req.body_area ?? 'Not specified',
      size_estimate: req.size_estimate ?? 'Not specified',
      mood_keywords: req.mood_keywords?.join(', ') ?? 'None',
      avoid_keywords: req.avoid_keywords?.join(', ') ?? 'None',
    }

    const userPrompt = hydratePrompt(template.user_prompt_template, ctx)

    // Build message content — include reference images if any
    type ContentBlock =
      | { type: 'text'; text: string }
      | { type: 'image'; source: { type: 'url'; url: string } }

    const contentBlocks: ContentBlock[] = [{ type: 'text', text: userPrompt }]

    if (req.reference_image_urls && req.reference_image_urls.length > 0) {
      for (const imgUrl of req.reference_image_urls.slice(0, 5)) {
        contentBlocks.push({
          type: 'image',
          source: { type: 'url', url: imgUrl },
        })
      }
    }

    log.info({ promptLength: userPrompt.length, hasImages: contentBlocks.length > 1 }, 'calling Claude API')
    const claudeStart = Date.now()

    let claudeResponse: Anthropic.Message
    try {
      claudeResponse = await anthropic.messages.create({
        model: 'claude-sonnet-4-20250514',
        max_tokens: 2048,
        system: template.system_prompt,
        messages: [
          {
            role: 'user',
            content: contentBlocks as Anthropic.MessageParam['content'],
          },
        ],
      })
    } catch (claudeErr) {
      // Retry once on timeout/server error
      if (claudeErr instanceof Anthropic.APIError && claudeErr.status >= 500) {
        log.warn({ err: claudeErr }, 'Claude API error — retrying once')
        claudeResponse = await anthropic.messages.create({
          model: 'claude-sonnet-4-20250514',
          max_tokens: 2048,
          system: template.system_prompt,
          messages: [{ role: 'user', content: contentBlocks as Anthropic.MessageParam['content'] }],
        })
      } else {
        throw claudeErr
      }
    }

    const claudeDurationMs = Date.now() - claudeStart
    const claudeInputTokens = claudeResponse.usage.input_tokens
    const claudeOutputTokens = claudeResponse.usage.output_tokens
    const claudeCost = claudeCostCents(claudeInputTokens, claudeOutputTokens)

    const responseText = claudeResponse.content
      .filter((b): b is Anthropic.TextBlock => b.type === 'text')
      .map((b) => b.text)
      .join('\n\n')

    log.info({ tokensIn: claudeInputTokens, tokensOut: claudeOutputTokens, costCents: claudeCost }, 'Claude analysis complete')

    // Insert text output
    const { data: textOutput, error: textInsertErr } = await supabase
      .from('ai_design_outputs')
      .insert({
        studio_id: studioId,
        request_id: requestId,
        sequence: nextSequence,
        prompt_text: userPrompt,
        system_prompt: template.system_prompt,
        model: 'claude-sonnet-4-20250514',
        response_text: responseText,
        tokens_input: claudeInputTokens,
        tokens_output: claudeOutputTokens,
        cost_cents: claudeCost,
        generation_time_ms: claudeDurationMs,
        status: 'completed',
      })
      .select('id')
      .single()

    if (textInsertErr || !textOutput) {
      log.error({ err: textInsertErr }, 'failed to insert text output')
      throw textInsertErr ?? new Error('text output insert returned null')
    }

    // Log Claude usage
    await supabase.from('ai_usage_log').insert({
      studio_id: studioId,
      request_id: requestId,
      output_id: textOutput.id,
      api_provider: 'anthropic',
      model: 'claude-sonnet-4-20250514',
      endpoint: 'messages',
      tokens_input: claudeInputTokens,
      tokens_output: claudeOutputTokens,
      cost_cents: claudeCost,
      duration_ms: claudeDurationMs,
      http_status: 200,
    })

    nextSequence++

    // --- Step 3: Image generation ---
    const imageProvider = (process.env['AI_IMAGE_PROVIDER'] ?? 'openai') as 'openai' | 'stability'
    const openaiKey = process.env['OPENAI_API_KEY']

    if (imageProvider === 'openai' && openaiKey) {
      const imagePromptText = buildImagePrompt(responseText.slice(0, 1000), req.style_category, req.body_area)
      const imagePromptFinal = template.image_prompt_template
        ? hydratePrompt(template.image_prompt_template, { ...ctx, description: imagePromptText })
        : imagePromptText

      log.info({ provider: 'openai', promptLength: imagePromptFinal.length }, 'calling DALL-E 3')
      const imageStart = Date.now()

      const openai = new OpenAI({ apiKey: openaiKey })
      const imageResponse = await openai.images.generate({
        model: 'dall-e-3',
        prompt: imagePromptFinal.slice(0, 4000), // DALL-E 3 limit
        size: '1024x1024',
        quality: 'hd',
        n: 1,
      })

      const imageDurationMs = Date.now() - imageStart
      const imageUrl = imageResponse.data?.[0]?.url

      if (!imageUrl) throw new Error('DALL-E 3 returned no image URL')

      // Download image and upload to Supabase Storage
      const imageBuffer = await fetch(imageUrl).then((r) => r.arrayBuffer())
      const storagePath = `${studioId}/ai/${requestId}/${nextSequence}.png`

      const { error: uploadErr } = await supabase
        .storage
        .from('design-assets')
        .upload(storagePath, Buffer.from(imageBuffer), {
          contentType: 'image/png',
          upsert: true,
        })

      if (uploadErr) {
        log.error({ err: uploadErr, storagePath }, 'image upload failed')
        throw uploadErr
      }

      const { data: publicUrlData } = supabase
        .storage
        .from('design-assets')
        .getPublicUrl(storagePath)

      const { data: imageOutput, error: imageInsertErr } = await supabase
        .from('ai_design_outputs')
        .insert({
          studio_id: studioId,
          request_id: requestId,
          sequence: nextSequence,
          prompt_text: imagePromptFinal,
          model: 'dall-e-3',
          image_url: publicUrlData?.publicUrl ?? storagePath,
          image_model: 'dall-e-3',
          image_prompt: imagePromptFinal,
          tokens_input: 0,
          tokens_output: 0,
          cost_cents: DALLE3_HD_COST_CENTS,
          generation_time_ms: imageDurationMs,
          status: 'completed',
        })
        .select('id')
        .single()

      if (imageInsertErr || !imageOutput) {
        log.error({ err: imageInsertErr }, 'failed to insert image output')
      } else {
        // Log image gen usage
        await supabase.from('ai_usage_log').insert({
          studio_id: studioId,
          request_id: requestId,
          output_id: imageOutput.id,
          api_provider: 'openai',
          model: 'dall-e-3',
          endpoint: 'images.generate',
          tokens_input: 0,
          tokens_output: 0,
          cost_cents: DALLE3_HD_COST_CENTS,
          duration_ms: imageDurationMs,
          http_status: 200,
        })
      }

      log.info({ durationMs: imageDurationMs, storagePath }, 'image generation complete')
    } else {
      log.info('image generation skipped — no image provider API key configured')
    }

    // The trigger handle_ai_output_request_completion will set request status = 'completed'
    log.info('AI design pipeline complete')
  } catch (err) {
    const failureReason = err instanceof Error ? err.message : String(err)
    log.error({ err }, 'AI design pipeline failed')

    await supabase
      .from('ai_design_requests')
      .update({
        status: 'failed',
        failed_at: new Date().toISOString(),
        failure_reason: failureReason,
      })
      .eq('id', requestId)

    throw err
  }
}

