'use client'

import { useCallback, useState } from 'react'
import { ImagePlus, X, AlertCircle } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { createClient } from '@/lib/supabase/client'
import { logger } from '@/lib/logger'

const ALLOWED_MIME = new Set(['image/jpeg', 'image/png', 'image/webp', 'image/heic'])
const MAX_SIZE_BYTES = 5 * 1024 * 1024 // 5 MB
const MAX_FILES = 5

interface UploadedRef {
  url: string
  name: string
  uploading?: boolean
  error?: string
}

interface Props {
  studioId: string
  requestId: string
  value: string[]
  onChange: (urls: string[]) => void
  error?: string
}

export function ReferenceImageUploader({ studioId, requestId, value, onChange, error }: Props) {
  const [uploads, setUploads] = useState<UploadedRef[]>(
    value.map((url) => ({ url, name: url.split('/').pop() ?? 'image' })),
  )

  const handleFiles = useCallback(
    async (files: FileList | null) => {
      if (!files) return
      const newFiles = Array.from(files).slice(0, MAX_FILES - uploads.length)

      for (const file of newFiles) {
        // Client-side validation
        if (!ALLOWED_MIME.has(file.type)) {
          setUploads((prev) => [
            ...prev,
            { url: '', name: file.name, error: 'File type not supported. Use JPEG, PNG, WebP, or HEIC.' },
          ])
          continue
        }
        if (file.size > MAX_SIZE_BYTES) {
          setUploads((prev) => [
            ...prev,
            { url: '', name: file.name, error: `File too large (max 5 MB). This file is ${(file.size / 1024 / 1024).toFixed(1)} MB.` },
          ])
          continue
        }

        const tempId = `${Date.now()}-${file.name}`
        setUploads((prev) => [...prev, { url: '', name: file.name, uploading: true }])

        try {
          const supabase = createClient()
          const ext = file.name.split('.').pop() ?? 'jpg'
          const refIndex = uploads.filter((u) => u.url).length + 1
          const path = `${studioId}/ai/${requestId}/ref_${refIndex}.${ext}`

          const { error: uploadErr } = await supabase
            .storage
            .from('design-assets')
            .upload(path, file, { contentType: file.type, upsert: true })

          if (uploadErr) throw uploadErr

          const { data: urlData } = supabase.storage.from('design-assets').getPublicUrl(path)
          const publicUrl = urlData.publicUrl

          setUploads((prev) =>
            prev.map((u) => (u.name === file.name && u.uploading ? { url: publicUrl, name: file.name } : u)),
          )
          onChange([...value, publicUrl])
        } catch (err) {
          logger.error({ err, fileName: file.name }, 'reference image upload failed')
          setUploads((prev) =>
            prev.map((u) =>
              u.name === file.name && u.uploading
                ? { url: '', name: file.name, error: 'Upload failed. Please try again.' }
                : u,
            ),
          )
          void tempId
        }
      }
    },
    [uploads, studioId, requestId, value, onChange],
  )

  function removeImage(index: number) {
    const updated = uploads.filter((_, i) => i !== index)
    setUploads(updated)
    onChange(updated.filter((u) => u.url).map((u) => u.url))
  }

  const canAddMore = uploads.length < MAX_FILES

  return (
    <div>
      <div className="grid grid-cols-3 gap-2 sm:grid-cols-5">
        {uploads.map((ref, i) => (
          <div key={i} className="relative aspect-square overflow-hidden rounded-lg border border-border bg-muted">
            {ref.uploading ? (
              <div className="flex h-full items-center justify-center">
                <div className="h-5 w-5 animate-spin rounded-full border-2 border-primary border-t-transparent" />
              </div>
            ) : ref.error ? (
              <div className="flex h-full flex-col items-center justify-center gap-1 p-2">
                <AlertCircle size={18} className="text-destructive" />
                <p className="text-center text-[9px] text-destructive leading-tight">{ref.error}</p>
              </div>
            ) : (
              // eslint-disable-next-line @next/next/no-img-element
              <img src={ref.url} alt={ref.name} className="h-full w-full object-cover" />
            )}
            <button
              type="button"
              onClick={() => removeImage(i)}
              aria-label="Remove image"
              className="absolute right-1 top-1 rounded-full bg-background/80 p-0.5 text-foreground backdrop-blur-sm hover:bg-destructive hover:text-destructive-foreground"
            >
              <X size={12} strokeWidth={2.5} />
            </button>
          </div>
        ))}

        {canAddMore && (
          <label className="flex aspect-square cursor-pointer flex-col items-center justify-center gap-1.5 rounded-lg border border-dashed border-border bg-muted/40 text-muted-foreground transition-colors hover:border-primary/50 hover:bg-muted/60">
            <ImagePlus size={20} strokeWidth={1.5} />
            <span className="text-xs">Add image</span>
            <input
              type="file"
              accept=".jpg,.jpeg,.png,.webp,.heic,image/jpeg,image/png,image/webp,image/heic"
              multiple
              className="sr-only"
              onChange={(e) => handleFiles(e.target.files)}
            />
          </label>
        )}
      </div>
      <p className="mt-1.5 text-xs text-muted-foreground">
        Up to {MAX_FILES} images, max 5 MB each. JPEG, PNG, WebP, HEIC.
      </p>
      {error && <p role="alert" className="mt-1 text-xs text-destructive">{error}</p>}
    </div>
  )
}

