'use client'

import { useState } from 'react'
import { Star } from 'lucide-react'

interface Props {
  value: number | null
  onChange: (rating: number) => Promise<void>
  readonly?: boolean
  size?: number
}

export function OutputRating({ value, onChange, readonly = false, size = 16 }: Props) {
  const [hovered, setHovered] = useState<number | null>(null)
  const [pending, setPending] = useState(false)

  const display = hovered ?? value ?? 0

  async function handleClick(rating: number) {
    if (readonly || pending) return
    setPending(true)
    try {
      await onChange(rating)
    } finally {
      setPending(false)
    }
  }

  return (
    <div className="flex items-center gap-0.5" aria-label={`Rating: ${value ?? 0} of 5 stars`}>
      {[1, 2, 3, 4, 5].map((star) => (
        <button
          key={star}
          type="button"
          onClick={() => handleClick(star)}
          onMouseEnter={() => !readonly && setHovered(star)}
          onMouseLeave={() => !readonly && setHovered(null)}
          disabled={readonly || pending}
          aria-label={`Rate ${star} star${star !== 1 ? 's' : ''}`}
          className={readonly ? 'cursor-default' : 'cursor-pointer'}
        >
          <Star
            size={size}
            strokeWidth={1.5}
            className={
              star <= display
                ? 'fill-amber-400 text-amber-400'
                : 'fill-transparent text-muted-foreground/30'
            }
          />
        </button>
      ))}
    </div>
  )
}

import { Progress } from '@/components/ui/progress'

interface Props {
  used: number
  quota: number | null // null = unlimited
}

export function UsageProgressBar({ used, quota }: Props) {
  if (quota === null) {
    return (
      <div className="flex items-center gap-2 text-xs text-muted-foreground">
        <span className="font-medium text-foreground">{used.toLocaleString()}</span>
        <span>generations used this month</span>
        <span className="rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:text-emerald-400">
          Unlimited
        </span>
      </div>
    )
  }

  const pct = Math.min(100, Math.round((used / quota) * 100))
  const remaining = Math.max(0, quota - used)
  const isWarning = pct >= 80
  const isDanger = pct >= 95

  return (
    <div className="flex flex-col gap-1.5">
      <div className="flex items-center justify-between text-xs">
        <span className="text-muted-foreground">
          <span className="font-medium text-foreground">{used.toLocaleString()}</span>
          {' / '}
          <span>{quota.toLocaleString()}</span>
          {' generations used'}
        </span>
        <span
          className={[
            'font-medium',
            isDanger ? 'text-destructive' : isWarning ? 'text-amber-600 dark:text-amber-400' : 'text-muted-foreground',
          ].join(' ')}
        >
          {remaining.toLocaleString()} remaining
        </span>
      </div>
      <Progress
        value={pct}
        className={[
          'h-1.5',
          isDanger ? '[&>div]:bg-destructive' : isWarning ? '[&>div]:bg-amber-500' : '',
        ].join(' ')}
      />
    </div>
  )
}

import Link from 'next/link'
