import { Badge } from '@/components/ui/badge'
import { OutputRating } from './OutputRating'
import type { AiDesignGalleryItem } from '@/lib/supabase/types'

const STATUS_CONFIG = {
  pending:    { label: 'Pending',    class: 'bg-secondary text-secondary-foreground' },
  processing: { label: 'Processing', class: 'bg-amber-500/10 text-amber-700 dark:text-amber-400' },
  completed:  { label: 'Completed',  class: 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-400' },
  failed:     { label: 'Failed',     class: 'bg-destructive/10 text-destructive' },
  cancelled:  { label: 'Cancelled',  class: 'bg-muted text-muted-foreground' },
} as const

const STYLE_LABELS: Record<string, string> = {
  blackwork: 'Blackwork', watercolor: 'Watercolor', traditional: 'Traditional',
  neo_trad: 'Neo Traditional', realism: 'Realism', geometric: 'Geometric',
  minimalist: 'Minimalist', japanese: 'Japanese', tribal: 'Tribal',
  trash_polka: 'Trash Polka', dotwork: 'Dotwork', illustrative: 'Illustrative',
  abstract: 'Abstract', lettering: 'Lettering', other: 'Other',
