  const imageOutput = outputs.find((o) => o.image_url)
  const avgRating = outputs.length > 0
    ? outputs.reduce((s, o) => s + (o.rating ?? 0), 0) / outputs.filter((o) => o.rating).length
    : null

  const statusCfg = STATUS_CONFIG[request.status as keyof typeof STATUS_CONFIG] ?? STATUS_CONFIG.pending

  return (
    <Link
      href={`/ai-design/${request.id}`}
      className="group block overflow-hidden rounded-xl border border-border bg-card shadow-card transition-all hover:border-primary/30 hover:shadow-soft-md"
    >
      {/* Thumbnail */}
      <div className="relative aspect-square w-full overflow-hidden bg-muted">
        {imageOutput?.image_url ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={imageOutput.image_url}
            alt={`${STYLE_LABELS[request.style_category] ?? request.style_category} design`}
            className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-105"
          />
        ) : (
          <div className="flex h-full items-center justify-center">
            <Wand2 size={32} strokeWidth={1.25} className="text-muted-foreground/40" />
          </div>
