        {/* Status overlay for processing */}
        {request.status === 'processing' && (
          <div className="absolute inset-0 flex items-center justify-center bg-background/60 backdrop-blur-sm">
            <div className="flex flex-col items-center gap-2">
              <div className="h-6 w-6 animate-spin rounded-full border-2 border-primary border-t-transparent" />
              <span className="text-xs font-medium text-foreground">Generating...</span>
            </div>
          </div>
        )}
      </div>

      {/* Card body */}
      <div className="flex flex-col gap-2 p-3">
        <div className="flex items-start justify-between gap-2">
          <Badge variant="secondary" className="text-[10px] font-medium">
            {STYLE_LABELS[request.style_category] ?? request.style_category}
          </Badge>
          <span className={['rounded-full px-2 py-0.5 text-[10px] font-medium', statusCfg.class].join(' ')}>
            {statusCfg.label}
          </span>
        </div>

        <div className="space-y-0.5">
          {request.body_area && (
            <p className="text-xs text-muted-foreground truncate">{request.body_area}</p>
          )}
          <p className="text-xs text-foreground line-clamp-2">{request.description}</p>
        </div>

        {avgRating != null && !isNaN(avgRating) && (
          <OutputRating value={Math.round(avgRating)} onChange={async () => {}} readonly size={12} />
        )}

        <p className="text-[10px] text-muted-foreground">
          {new Date(request.created_at).toLocaleDateString()}
        </p>
      </div>
    </Link>
  )
}

'use client'

import { useState, useTransition, useId } from 'react'
import { useRouter } from 'next/navigation'
import { z } from 'zod'
import { toast } from 'sonner'
import { Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { StyleCategoryPicker } from './StyleCategoryPicker'
import { BodyAreaInput } from './BodyAreaInput'
import { MoodKeywordsInput } from './MoodKeywordsInput'
import { ReferenceImageUploader } from './ReferenceImageUploader'
import type { AiStyleCategory } from '@/lib/supabase/types'

const SIZE_OPTIONS = [
  { value: 'small',          label: 'Small (1–3 in)' },
  { value: 'medium',         label: 'Medium (3–6 in)' },
  { value: 'large',          label: 'Large (6–10 in)' },
  { value: 'sleeve',         label: 'Full Sleeve' },
  { value: 'half-sleeve',    label: 'Half Sleeve' },
  { value: 'full-back',      label: 'Full Back' },
  { value: 'quarter-sleeve', label: 'Quarter Sleeve' },
] as const

const FormSchema = z.object({
  style_category: z.string().min(1, 'Please select a style'),
  description: z.string().min(10, 'Description must be at least 10 characters').max(2000),
  body_area: z.string().max(100).optional(),
  size_estimate: z.string().optional(),
  mood_keywords: z.array(z.string()).optional(),
  avoid_keywords: z.array(z.string()).optional(),
  reference_image_urls: z.array(z.string().url()).max(5).optional(),
  budget_min: z.string().optional(),
  budget_max: z.string().optional(),
})

interface Props {
  studioId: string
  /** Pre-fill request ID for reference image uploads (generated client-side) */
  draftRequestId: string
  onCancel?: () => void
}

export function NewDesignRequestForm({ studioId, draftRequestId, onCancel }: Props) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const descriptionId = useId()
  const [errors, setErrors] = useState<Partial<Record<string, string>>>({})

  const [styleCategory, setStyleCategory] = useState<AiStyleCategory | ''>('')
  const [description, setDescription] = useState('')
  const [bodyArea, setBodyArea] = useState('')
  const [sizeEstimate, setSizeEstimate] = useState('')
  const [moodKeywords, setMoodKeywords] = useState<string[]>([])
  const [avoidKeywords, setAvoidKeywords] = useState<string[]>([])
  const [referenceUrls, setReferenceUrls] = useState<string[]>([])
  const [budgetMin, setBudgetMin] = useState('')
  const [budgetMax, setBudgetMax] = useState('')

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    setErrors({})

    const parsed = FormSchema.safeParse({
      style_category: styleCategory,
      description,
      body_area: bodyArea || undefined,
      size_estimate: sizeEstimate || undefined,
      mood_keywords: moodKeywords,
      avoid_keywords: avoidKeywords,
      reference_image_urls: referenceUrls,
      budget_min: budgetMin || undefined,
      budget_max: budgetMax || undefined,
    })

    if (!parsed.success) {
      const flat = parsed.error.flatten().fieldErrors
      setErrors(
        Object.fromEntries(
          Object.entries(flat).map(([k, v]) => [k, v?.[0] ?? '']),
        ),
      )
      return
    }

    const minCents = budgetMin ? Math.round(parseFloat(budgetMin) * 100) : undefined
    const maxCents = budgetMax ? Math.round(parseFloat(budgetMax) * 100) : undefined

    startTransition(async () => {
      try {
        const res = await fetch('/api/ai/requests', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            studio_id: studioId,
            style_category: styleCategory,
            description,
            body_area: bodyArea || undefined,
            size_estimate: sizeEstimate || undefined,
            mood_keywords: moodKeywords.length > 0 ? moodKeywords : undefined,
            avoid_keywords: avoidKeywords.length > 0 ? avoidKeywords : undefined,
            reference_image_urls: referenceUrls.length > 0 ? referenceUrls : undefined,
            budget_min_cents: minCents,
            budget_max_cents: maxCents,
          }),
        })

        const json = await res.json() as { data?: { id: string }; error?: string; requiredPlan?: string }

        if (!res.ok) {
          if (res.status === 403 && json.requiredPlan) {
            toast.error('AI Design Assistant requires Pro plan or higher')
          } else if (res.status === 429) {
            toast.error(json.error ?? 'Rate limit exceeded. Please wait a moment.')
          } else {
            toast.error(json.error ?? 'Failed to create design request')
          }
          return
        }

        toast.success('Design request submitted — generating your AI moodboard')
        router.push(`/ai-design/${json.data!.id}`)
      } catch {
        toast.error('Failed to submit request. Please try again.')
      }
    })
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      {/* Style category */}
      <div className="space-y-2">
        <Label>Style category <span className="text-destructive">*</span></Label>
        <StyleCategoryPicker
          value={styleCategory}
          onChange={setStyleCategory}
          error={errors.style_category}
        />
      </div>

      {/* Description */}
      <div className="space-y-2">
        <Label htmlFor={descriptionId}>
          Description <span className="text-destructive">*</span>
        </Label>
        <Textarea
          id={descriptionId}
          rows={4}
          placeholder="Describe what your client wants — the more detail the better. Include subject matter, style influences, meaningful elements, color preferences..."
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          maxLength={2000}
          aria-invalid={!!errors.description}
          aria-describedby={errors.description ? 'desc-error' : undefined}
          className="resize-none"
        />
        <div className="flex items-center justify-between">
          {errors.description ? (
            <p id="desc-error" role="alert" className="text-xs text-destructive">{errors.description}</p>
          ) : (
            <span />
          )}
          <span className="text-xs text-muted-foreground">{description.length}/2000</span>
        </div>
      </div>

      {/* Body area + size */}
      <div className="grid gap-4 sm:grid-cols-2">
        <div className="space-y-2">
          <Label htmlFor="body_area">Body area</Label>
          <BodyAreaInput
            value={bodyArea}
            onChange={setBodyArea}
            error={errors.body_area}
          />
        </div>
        <div className="space-y-2">
          <Label htmlFor="size_estimate">Size estimate</Label>
          <Select value={sizeEstimate} onValueChange={setSizeEstimate}>
            <SelectTrigger>
              <SelectValue placeholder="Select size..." />
            </SelectTrigger>
            <SelectContent>
              {SIZE_OPTIONS.map((o) => (
                <SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Reference images */}
      <div className="space-y-2">
        <Label>Reference images (optional)</Label>
        <ReferenceImageUploader
          studioId={studioId}
          requestId={draftRequestId}
          value={referenceUrls}
          onChange={setReferenceUrls}
        />
      </div>

      {/* Mood keywords */}
      <div className="space-y-2">
        <Label>Mood / themes</Label>
        <MoodKeywordsInput
          label="Mood keywords"
          value={moodKeywords}
          onChange={setMoodKeywords}
          placeholder="e.g. dark, mystical, nature, bold..."
        />
      </div>

      {/* Avoid keywords */}
      <div className="space-y-2">
        <Label>Elements to avoid</Label>
        <MoodKeywordsInput
          label="Avoid keywords"
          value={avoidKeywords}
          onChange={setAvoidKeywords}
          placeholder="e.g. skulls, color, text..."
        />
      </div>

      {/* Budget */}
      <div className="space-y-2">
        <Label>Budget range (optional)</Label>
        <div className="flex items-center gap-3">
          <div className="relative flex-1">
            <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-sm text-muted-foreground">$</span>
            <Input
              type="number"
              placeholder="Min"
              value={budgetMin}
              onChange={(e) => setBudgetMin(e.target.value)}
              min={0}
              className="pl-6"
            />
          </div>
          <span className="text-muted-foreground">–</span>
          <div className="relative flex-1">
            <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-sm text-muted-foreground">$</span>
            <Input
              type="number"
              placeholder="Max"
              value={budgetMax}
              onChange={(e) => setBudgetMax(e.target.value)}
              min={0}
              className="pl-6"
            />
          </div>
        </div>
      </div>

      {/* Footer actions */}
      <div className="flex items-center justify-end gap-3 border-t border-border pt-4">
        {onCancel && (
          <Button type="button" variant="ghost" onClick={onCancel} disabled={isPending}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isPending}>
          {isPending ? (
            <>
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              Submitting...
            </>
          ) : (
            'Generate AI Design'
          )}
        </Button>
      </div>
    </form>
  )
}

