import { Wand2 } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import { OutputRating } from './OutputRating'
import type { AiDesignOutput } from '@/lib/supabase/types'

const STATUS_CONFIG: Record<string, { label: string; class: string }> = {
  pending:    { label: 'Pending',    class: 'bg-secondary text-secondary-foreground' },
  generating: { label: 'Generating', class: 'bg-amber-500/10 text-amber-700 dark:text-amber-400' },
  completed:  { label: 'Completed',  class: 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-400' },
  failed:     { label: 'Failed',     class: 'bg-destructive/10 text-destructive' },
  rejected:   { label: 'Rejected',   class: 'bg-muted text-muted-foreground' },
  approved:   { label: 'Approved',   class: 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-400' },
}

interface Props {
  output: AiDesignOutput
  onRatingChange?: (outputId: string, rating: number) => Promise<void>
}

export function OutputCard({ output, onRatingChange }: Props) {
  const statusCfg = STATUS_CONFIG[output.status] ?? STATUS_CONFIG.pending
  const isImage = !!output.image_url
  const isText = !!output.response_text

  return (
    <div className="overflow-hidden rounded-xl border border-border bg-card shadow-card">
      {/* Image output */}
      {isImage && (
        <div className="relative aspect-square w-full overflow-hidden bg-muted">
          {output.status === 'generating' ? (
            <div className="flex h-full items-center justify-center">
              <div className="flex flex-col items-center gap-3">
                <div className="h-7 w-7 animate-spin rounded-full border-2 border-primary border-t-transparent" />
                <span className="text-xs font-medium text-muted-foreground">Generating image…</span>
              </div>
            </div>
          ) : (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={output.image_url!}
              alt={`AI generated design — sequence ${output.sequence}`}
              className="h-full w-full object-cover"
            />
          )}
          {/* Approved badge overlay */}
          {output.status === 'approved' && (
            <div className="absolute left-2 top-2">
              <span className="rounded-full bg-emerald-500 px-2 py-0.5 text-[10px] font-semibold text-white shadow">
                Approved
              </span>
            </div>
          )}
        </div>
      )}

      <div className="space-y-3 p-4">
        {/* Header row */}
        <div className="flex items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <Wand2 size={13} strokeWidth={1.75} className="shrink-0 text-muted-foreground" />
            <span className="text-xs font-medium text-foreground">
              {isImage ? 'Generated image' : 'Moodboard analysis'}
            </span>
            <Badge variant="secondary" className="text-[10px]">
              #{output.sequence}
            </Badge>
          </div>
          <span
            className={[
              'rounded-full px-2 py-0.5 text-[10px] font-medium',
              statusCfg.class,
            ].join(' ')}
          >
            {statusCfg.label}
          </span>
        </div>

        {/* Text output — moodboard analysis */}
        {isText && (
          <div className="rounded-lg bg-muted/40 p-3">
            <p className="whitespace-pre-wrap text-xs leading-relaxed text-foreground">
              {output.response_text}
            </p>
          </div>
        )}

        {/* Image prompt used */}
        {isImage && output.image_prompt && (
          <details className="group">
            <summary className="cursor-pointer list-none text-xs text-muted-foreground hover:text-foreground">
              <span className="group-open:hidden">Show prompt</span>
              <span className="hidden group-open:inline">Hide prompt</span>
            </summary>
            <p className="mt-1.5 rounded-lg bg-muted/40 p-2.5 text-[11px] leading-relaxed text-muted-foreground">
              {output.image_prompt}
            </p>
          </details>
        )}

        {/* Artist notes */}
        {output.artist_notes && (
          <div className="border-t border-border pt-2">
            <p className="text-[11px] text-muted-foreground">
              <span className="font-medium text-foreground">Notes: </span>
              {output.artist_notes}
            </p>
          </div>
        )}

        {/* Rating */}
        {output.status === 'completed' || output.status === 'approved' ? (
          <div className="flex items-center justify-between gap-2 border-t border-border pt-2">
            <span className="text-[11px] text-muted-foreground">Rating</span>
            <OutputRating
              value={output.rating}
              onChange={
                onRatingChange
                  ? (r) => onRatingChange(output.id, r)
                  : async () => {}
              }
              readonly={!onRatingChange}
              size={14}
            />
          </div>
        ) : null}

        {/* Meta */}
        <div className="flex items-center justify-between text-[10px] text-muted-foreground">
          <span>{output.model}</span>
          {output.generation_time_ms != null && (
            <span>{(output.generation_time_ms / 1000).toFixed(1)}s</span>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { Check, X, Share2, RefreshCw, Loader2, StickyNote } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import type { AiDesignOutput, AiRequestStatus } from '@/lib/supabase/types'

interface Props {
  output: AiDesignOutput
  requestId: string
  requestStatus: AiRequestStatus
  studioId: string
  onApproved?: (outputId: string) => void
  onRejected?: (outputId: string) => void
  onShared?: (outputId: string, token: string) => void
  onRegenerate?: () => void
}

export function OutputActions({
  output,
  requestStatus,
  onApproved,
  onRejected,
  onShared,
  onRegenerate,
}: Props) {
  const [approving, setApproving] = useState(false)
  const [rejecting, setRejecting] = useState(false)
  const [sharing, setSharing] = useState(false)
  const [regenerating, setRegenerating] = useState(false)

  const [notesOpen, setNotesOpen] = useState(false)
  const [notesText, setNotesText] = useState(output.artist_notes ?? '')
  const [savingNotes, setSavingNotes] = useState(false)

  const isCompleted = output.status === 'completed'
  const isApproved = output.status === 'approved'
  const canAct = isCompleted || isApproved
  const canRegenerate = requestStatus === 'completed' || requestStatus === 'failed'

  async function handleApprove() {
    if (!canAct) return
    setApproving(true)
    try {
      const res = await fetch(`/api/ai/outputs/${output.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'approve' }),
      })
      if (!res.ok) throw new Error('Failed to approve')
      toast.success('Output approved')
      onApproved?.(output.id)
    } catch {
      toast.error('Failed to approve output')
    } finally {
      setApproving(false)
    }
  }

  async function handleReject() {
    if (!canAct) return
    setRejecting(true)
    try {
      const res = await fetch(`/api/ai/outputs/${output.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'reject' }),
      })
      if (!res.ok) throw new Error('Failed to reject')
      toast.success('Output rejected')
      onRejected?.(output.id)
    } catch {
      toast.error('Failed to reject output')
    } finally {
      setRejecting(false)
    }
  }

  async function handleShare() {
    setSharing(true)
    try {
      const res = await fetch(`/api/ai/outputs/${output.id}/share`, {
        method: 'POST',
      })
      const json = await res.json() as { sharePageUrl?: string; token?: string; error?: string }
      if (!res.ok) throw new Error(json.error ?? 'Failed to share')
      if (json.sharePageUrl) {
        await navigator.clipboard.writeText(json.sharePageUrl).catch(() => {})
        toast.success('Share link copied to clipboard')
        onShared?.(output.id, json.token ?? '')
      }
    } catch {
      toast.error('Failed to generate share link')
    } finally {
      setSharing(false)
    }
  }

  async function handleRegenerate() {
    if (!canRegenerate || !onRegenerate) return
    setRegenerating(true)
    try {
      const res = await fetch(`/api/ai/requests/${output.request_id}/regenerate`, {
        method: 'POST',
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to regenerate')
      }
      toast.success('Regenerating — new outputs will appear shortly')
      onRegenerate()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to regenerate')
    } finally {
      setRegenerating(false)
    }
  }

  async function handleSaveNotes() {
    setSavingNotes(true)
    try {
      const res = await fetch(`/api/ai/outputs/${output.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'notes', notes: notesText }),
      })
      if (!res.ok) throw new Error('Failed to save notes')
      toast.success('Notes saved')
      setNotesOpen(false)
    } catch {
      toast.error('Failed to save notes')
    } finally {
      setSavingNotes(false)
    }
  }

  return (
    <>
      <div className="flex flex-wrap items-center gap-2">
        {/* Approve */}
        {isCompleted && (
          <Button
            size="sm"
            variant="outline"
            onClick={handleApprove}
            disabled={approving}
            className="h-7 px-2.5 text-xs text-emerald-700 hover:bg-emerald-50 hover:text-emerald-700 dark:text-emerald-400 dark:hover:bg-emerald-950"
          >
            {approving ? (
              <Loader2 className="mr-1 h-3 w-3 animate-spin" />
            ) : (
              <Check className="mr-1 h-3 w-3" />
            )}
            Approve
          </Button>
        )}

        {/* Reject */}
        {(isCompleted || isApproved) && (
          <Button
            size="sm"
            variant="outline"
            onClick={handleReject}
            disabled={rejecting}
            className="h-7 px-2.5 text-xs text-destructive hover:bg-destructive/10"
          >
            {rejecting ? (
              <Loader2 className="mr-1 h-3 w-3 animate-spin" />
            ) : (
              <X className="mr-1 h-3 w-3" />
            )}
            Reject
          </Button>
        )}

        {/* Share with client */}
        {(isCompleted || isApproved) && output.image_url && (
          <Button
            size="sm"
            variant="outline"
            onClick={handleShare}
            disabled={sharing}
            className="h-7 px-2.5 text-xs"
          >
            {sharing ? (
              <Loader2 className="mr-1 h-3 w-3 animate-spin" />
            ) : (
              <Share2 className="mr-1 h-3 w-3" />
            )}
            {output.shared_with_client ? 'Reshare' : 'Share with client'}
          </Button>
        )}

        {/* Artist notes */}
        <Button
          size="sm"
          variant="ghost"
          onClick={() => setNotesOpen(true)}
          className="h-7 px-2.5 text-xs"
        >
          <StickyNote className="mr-1 h-3 w-3" />
          Notes
        </Button>

        {/* Regenerate — only on latest output when request is done */}
        {canRegenerate && onRegenerate && (
          <Button
            size="sm"
            variant="ghost"
            onClick={handleRegenerate}
            disabled={regenerating}
            className="ml-auto h-7 px-2.5 text-xs"
          >
            {regenerating ? (
              <Loader2 className="mr-1 h-3 w-3 animate-spin" />
            ) : (
              <RefreshCw className="mr-1 h-3 w-3" />
            )}
            Regenerate
          </Button>
        )}
      </div>

      {/* Notes dialog */}
      <Dialog open={notesOpen} onOpenChange={setNotesOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="text-sm font-semibold">Artist notes</DialogTitle>
          </DialogHeader>
          <Textarea
            rows={4}
            placeholder="Internal notes about this output — not visible to clients."
            value={notesText}
            onChange={(e) => setNotesText(e.target.value)}
            maxLength={1000}
            className="resize-none text-sm"
          />
          <DialogFooter>
            <Button variant="ghost" size="sm" onClick={() => setNotesOpen(false)} disabled={savingNotes}>
              Cancel
            </Button>
            <Button size="sm" onClick={handleSaveNotes} disabled={savingNotes}>
              {savingNotes ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
              Save notes
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  )
}

'use client'

import { useState, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { ArrowLeft, ChevronLeft, ChevronRight, AlertTriangle } from 'lucide-react'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { OutputCard } from './OutputCard'
import { OutputActions } from './OutputActions'
import { UsageProgressBar } from './UsageProgressBar'
import type { AiDesignRequest, AiDesignOutput, AiRequestStatus } from '@/lib/supabase/types'

const STYLE_LABELS: Record<string, string> = {
  blackwork: 'Blackwork', watercolor: 'Watercolor', traditional: 'Traditional',
  neo_trad: 'Neo Traditional', realism: 'Realism', geometric: 'Geometric',
  minimalist: 'Minimalist', japanese: 'Japanese', tribal: 'Tribal',
  trash_polka: 'Trash Polka', dotwork: 'Dotwork', illustrative: 'Illustrative',
  abstract: 'Abstract', lettering: 'Lettering', other: 'Other',
}

const SIZE_LABELS: Record<string, string> = {
  small: 'Small (1–3 in)', medium: 'Medium (3–6 in)', large: 'Large (6–10 in)',
  sleeve: 'Full Sleeve', 'half-sleeve': 'Half Sleeve', 'full-back': 'Full Back',
  'quarter-sleeve': 'Quarter Sleeve',
}

const STATUS_CONFIG: Record<AiRequestStatus, { label: string; class: string }> = {
  pending:    { label: 'Pending',    class: 'bg-secondary text-secondary-foreground' },
  processing: { label: 'Processing', class: 'bg-amber-500/10 text-amber-700 dark:text-amber-400' },
  completed:  { label: 'Completed',  class: 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-400' },
  failed:     { label: 'Failed',     class: 'bg-destructive/10 text-destructive' },
  cancelled:  { label: 'Cancelled',  class: 'bg-muted text-muted-foreground' },
}

interface RequestDetailData {
  request: AiDesignRequest
  outputs: AiDesignOutput[]
  usageUsed?: number
  usageQuota?: number | null
}

interface Props {
  requestId: string
  studioId: string
}

async function fetchRequestDetail(requestId: string): Promise<RequestDetailData> {
  const res = await fetch(`/api/ai/requests/${requestId}`)
  if (!res.ok) throw new Error('Failed to load request')
  const json = await res.json() as RequestDetailData
  return json
}

async function rateOutput(outputId: string, rating: number): Promise<void> {
  const res = await fetch(`/api/ai/outputs/${outputId}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ action: 'rate', rating }),
  })
  if (!res.ok) throw new Error('Failed to save rating')
}

export function RequestDetailView({ requestId, studioId }: Props) {
  const router = useRouter()
  const queryClient = useQueryClient()
  const [refCarouselIdx, setRefCarouselIdx] = useState(0)

  const queryKey = ['ai-request', requestId]

  const { data, isLoading, isError } = useQuery({
    queryKey,
    queryFn: () => fetchRequestDetail(requestId),
    // Poll while processing
    refetchInterval: (q) => {
      const status = q.state.data?.request.status
      return status === 'pending' || status === 'processing' ? 4000 : false
    },
    staleTime: 15_000,
  })

  const invalidate = useCallback(() => {
    void queryClient.invalidateQueries({ queryKey })
    void queryClient.invalidateQueries({ queryKey: ['ai-gallery'] })
  }, [queryClient, queryKey])

  async function handleRating(outputId: string, rating: number) {
    await rateOutput(outputId, rating)
    void queryClient.invalidateQueries({ queryKey })
    toast.success('Rating saved')
  }

  async function handleCancel() {
    try {
      const res = await fetch(`/api/ai/requests/${requestId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'cancel' }),
      })
      if (!res.ok) throw new Error('Failed to cancel')
      toast.success('Request cancelled')
      invalidate()
    } catch {
      toast.error('Failed to cancel request')
    }
  }

  if (isLoading) {
    return (
      <div className="mx-auto max-w-4xl space-y-6 p-6">
        <Skeleton className="h-8 w-48" />
        <div className="grid gap-4 sm:grid-cols-2">
          <Skeleton className="h-40" />
          <Skeleton className="h-40" />
        </div>
        <Skeleton className="h-64" />
      </div>
    )
  }

  if (isError || !data) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-center">
        <AlertTriangle size={32} strokeWidth={1.25} className="mb-3 text-destructive" />
        <p className="text-sm font-medium">Could not load this design request.</p>
        <Button variant="ghost" size="sm" className="mt-3" onClick={() => router.back()}>
          Go back
        </Button>
      </div>
    )
  }

  const { request, outputs, usageUsed, usageQuota } = data
  const refImages = request.reference_image_urls ?? []
  const statusCfg = STATUS_CONFIG[request.status]
  const isProcessing = request.status === 'pending' || request.status === 'processing'

  return (
    <div className="mx-auto max-w-4xl space-y-6 p-6">
      {/* Back + header */}
      <div className="flex items-center justify-between gap-4">
        <Link
          href="/ai-design"
          className="flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground"
        >
          <ArrowLeft size={15} />
          AI Design
        </Link>

        <div className="flex items-center gap-2">
          <span
            className={[
              'rounded-full px-2.5 py-0.5 text-xs font-medium',
              statusCfg.class,
            ].join(' ')}
          >
            {statusCfg.label}
          </span>

          {(request.status === 'pending' || request.status === 'processing') && (
            <Button variant="ghost" size="sm" className="h-7 px-2.5 text-xs" onClick={handleCancel}>
              Cancel
            </Button>
          )}
        </div>
      </div>

      {/* Request metadata card */}
      <div className="rounded-xl border border-border bg-card p-5 shadow-card">
        <div className="mb-4 flex flex-wrap items-start gap-3">
          <Badge variant="secondary" className="text-xs">
            {STYLE_LABELS[request.style_category] ?? request.style_category}
          </Badge>
          {request.body_area && (
            <span className="text-xs text-muted-foreground">{request.body_area}</span>
          )}
          {request.size_estimate && (
            <span className="text-xs text-muted-foreground">
              {SIZE_LABELS[request.size_estimate] ?? request.size_estimate}
            </span>
          )}
          {(request.budget_min_cents || request.budget_max_cents) && (
            <span className="text-xs text-muted-foreground">
              {request.budget_min_cents
                ? `$${(request.budget_min_cents / 100).toLocaleString()}`
                : ''}
              {request.budget_min_cents && request.budget_max_cents ? ' – ' : ''}
              {request.budget_max_cents
                ? `$${(request.budget_max_cents / 100).toLocaleString()}`
                : ''}
            </span>
          )}
        </div>

        <p className="text-sm leading-relaxed text-foreground">{request.description}</p>

        {/* Mood / avoid keywords */}
        {((request.mood_keywords?.length ?? 0) > 0 ||
          (request.avoid_keywords?.length ?? 0) > 0) && (
          <div className="mt-4 flex flex-wrap gap-4">
            {(request.mood_keywords?.length ?? 0) > 0 && (
              <div className="space-y-1.5">
                <span className="text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
                  Mood
                </span>
                <div className="flex flex-wrap gap-1.5">
                  {request.mood_keywords!.map((k) => (
                    <span
                      key={k}
                      className="rounded-full bg-muted px-2 py-0.5 text-xs text-foreground"
                    >
                      {k}
                    </span>
                  ))}
                </div>
              </div>
            )}
            {(request.avoid_keywords?.length ?? 0) > 0 && (
              <div className="space-y-1.5">
                <span className="text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
                  Avoid
                </span>
                <div className="flex flex-wrap gap-1.5">
                  {request.avoid_keywords!.map((k) => (
                    <span
                      key={k}
                      className="rounded-full bg-destructive/10 px-2 py-0.5 text-xs text-destructive"
                    >
                      {k}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {/* Failed reason */}
        {request.status === 'failed' && request.failure_reason && (
          <div className="mt-4 flex items-start gap-2 rounded-lg bg-destructive/10 p-3">
            <AlertTriangle size={14} className="mt-0.5 shrink-0 text-destructive" />
            <p className="text-xs text-destructive">{request.failure_reason}</p>
          </div>
        )}

        {/* Footer meta */}
        <div className="mt-4 flex flex-wrap items-center justify-between gap-2 border-t border-border pt-3 text-[11px] text-muted-foreground">
          <span>Created {new Date(request.created_at).toLocaleString()}</span>
          {request.total_cost_cents > 0 && (
            <span>
              Cost: ${(request.total_cost_cents / 100).toFixed(4)}
              {' · '}
              {request.total_tokens_used.toLocaleString()} tokens
            </span>
          )}
        </div>
      </div>

      {/* Reference image carousel */}
      {refImages.length > 0 && (
        <div className="space-y-2">
          <h3 className="text-sm font-medium">Reference images</h3>
          <div className="relative flex items-center gap-2">
            {refImages.length > 1 && (
              <button
                type="button"
                onClick={() => setRefCarouselIdx((i) => (i - 1 + refImages.length) % refImages.length)}
                className="rounded-full bg-card p-1 shadow hover:bg-muted"
                aria-label="Previous reference image"
              >
                <ChevronLeft size={16} />
              </button>
            )}
            <div className="relative aspect-square w-40 shrink-0 overflow-hidden rounded-xl border border-border">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={refImages[refCarouselIdx]}
                alt={`Reference ${refCarouselIdx + 1}`}
                className="h-full w-full object-cover"
              />
            </div>
            {refImages.length > 1 && (
              <button
                type="button"
                onClick={() => setRefCarouselIdx((i) => (i + 1) % refImages.length)}
                className="rounded-full bg-card p-1 shadow hover:bg-muted"
                aria-label="Next reference image"
              >
                <ChevronRight size={16} />
              </button>
            )}
            {refImages.length > 1 && (
              <span className="ml-2 text-xs text-muted-foreground">
                {refCarouselIdx + 1} / {refImages.length}
              </span>
            )}
          </div>
        </div>
      )}

      {/* Processing state */}
      {isProcessing && (
        <div className="flex items-center gap-3 rounded-xl border border-border bg-card p-4 shadow-card">
          <div className="h-5 w-5 animate-spin rounded-full border-2 border-primary border-t-transparent" />
          <div>
            <p className="text-sm font-medium">
              {request.status === 'pending' ? 'Queued' : 'Generating your moodboard…'}
            </p>
            <p className="text-xs text-muted-foreground">
              {request.status === 'pending'
                ? 'Your request is queued and will begin processing shortly.'
                : 'Claude is analyzing your brief and generating image concepts. This takes 30–60 seconds.'}
            </p>
          </div>
        </div>
      )}

      {/* Outputs timeline */}
      {outputs.length > 0 && (
        <div className="space-y-4">
          <h3 className="text-sm font-medium">Generated outputs</h3>
          <div className="space-y-6">
            {outputs.map((output, idx) => (
              <div key={output.id} className="space-y-2">
                <OutputCard
                  output={output}
                  onRatingChange={handleRating}
                />
                {/* Actions only on last output for regenerate */}
                <OutputActions
                  output={output}
                  requestId={requestId}
                  requestStatus={request.status}
                  studioId={studioId}
                  onApproved={() => invalidate()}
                  onRejected={() => invalidate()}
                  onShared={() => invalidate()}
                  onRegenerate={idx === outputs.length - 1 ? () => invalidate() : undefined}
                />
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Usage bar (if data provided) */}
      {usageUsed != null && (
        <div className="rounded-xl border border-border bg-card p-4 shadow-card">
          <h3 className="mb-3 text-xs font-medium uppercase tracking-wider text-muted-foreground">
            Monthly usage
          </h3>
          <UsageProgressBar used={usageUsed} quota={usageQuota ?? null} />
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { Plus, Pencil, Trash2, Loader2, Lock } from 'lucide-react'
import { z } from 'zod'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
