const TemplateFormSchema = z.object({
  name: z.string().min(1, 'Name required').max(100),
  style_category: z.string().min(1, 'Style required') as z.ZodType<AiStyleCategory>,
  system_prompt: z.string().min(20, 'System prompt must be at least 20 characters').max(4000),
  user_prompt_template: z.string().min(20, 'User prompt template must be at least 20 characters').max(4000),
  image_prompt_template: z.string().max(2000).optional(),
})

type TemplateFormValues = z.infer<typeof TemplateFormSchema>

interface TemplatesResponse {
  system: AiDesignTemplate[]
  custom: AiDesignTemplate[]
}

interface Props {
  studioId: string
}

async function fetchTemplates(): Promise<TemplatesResponse> {
  const res = await fetch('/api/ai/templates')
  if (!res.ok) throw new Error('Failed to load templates')
  return res.json() as Promise<TemplatesResponse>
}

const QUERY_KEY = ['ai-templates']

export function PromptTemplateEditor({ studioId }: Props) {
  void studioId
  const queryClient = useQueryClient()
  const [isPending, startTransition] = useTransition()

  const [editTarget, setEditTarget] = useState<AiDesignTemplate | null>(null)
  const [createOpen, setCreateOpen] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<AiDesignTemplate | null>(null)
  const [formErrors, setFormErrors] = useState<Partial<Record<string, string>>>({})

  const [form, setForm] = useState<TemplateFormValues>({
    name: '',
    style_category: 'blackwork',
    system_prompt: '',
    user_prompt_template: '',
    image_prompt_template: '',
  })

  const { data, isLoading, isError } = useQuery({
    queryKey: QUERY_KEY,
    queryFn: fetchTemplates,
    staleTime: 60_000,
  })

  function openCreate() {
    setForm({ name: '', style_category: 'blackwork', system_prompt: '', user_prompt_template: '', image_prompt_template: '' })
    setFormErrors({})
    setCreateOpen(true)
  }

  function openEdit(t: AiDesignTemplate) {
    setForm({
      name: t.name,
      style_category: t.style_category,
      system_prompt: t.system_prompt,
      user_prompt_template: t.user_prompt_template,
      image_prompt_template: t.image_prompt_template ?? '',
    })
    setFormErrors({})
    setEditTarget(t)
  }

  function setField<K extends keyof TemplateFormValues>(key: K, value: TemplateFormValues[K]) {
    setForm((prev) => ({ ...prev, [key]: value }))
    setFormErrors((prev) => ({ ...prev, [key]: undefined }))
  }

  function handleSave() {
    const parsed = TemplateFormSchema.safeParse(form)
    if (!parsed.success) {
      const flat = parsed.error.flatten().fieldErrors
      setFormErrors(Object.fromEntries(Object.entries(flat).map(([k, v]) => [k, v?.[0] ?? ''])))
      return
    }

    const payload = {
      ...parsed.data,
      image_prompt_template: parsed.data.image_prompt_template || null,
    }

    startTransition(async () => {
      try {
        const isEdit = !!editTarget

        const res = await fetch(
          isEdit ? `/api/ai/templates/${editTarget!.id}` : '/api/ai/templates',
          {
            method: isEdit ? 'PATCH' : 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
          },
        )

        if (!res.ok) {
          const json = await res.json() as { error?: string }
          throw new Error(json.error ?? 'Failed to save template')
        }

        toast.success(isEdit ? 'Template updated' : 'Template created')
        void queryClient.invalidateQueries({ queryKey: QUERY_KEY })
        setEditTarget(null)
        setCreateOpen(false)
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Failed to save template')
      }
    })
  }

  async function handleDelete() {
    if (!deleteTarget) return
    try {
      const res = await fetch(`/api/ai/templates/${deleteTarget.id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to delete template')
      toast.success('Template deleted')
      void queryClient.invalidateQueries({ queryKey: QUERY_KEY })
      setDeleteTarget(null)
    } catch {
      toast.error('Failed to delete template')
    }
  }

  const isFormOpen = createOpen || !!editTarget

  return (
    <div className="space-y-6">
      {/* System templates (read-only) */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-sm font-medium">System templates</h3>
            <p className="text-xs text-muted-foreground">
              Built-in templates provided by InkOS. Read-only — create custom templates to override.
            </p>
          </div>
        </div>

        {isLoading ? (
          <div className="space-y-2">
            {[1, 2, 3].map((i) => <Skeleton key={i} className="h-12 w-full rounded-lg" />)}
          </div>
        ) : isError ? (
          <p className="text-xs text-destructive">Failed to load templates.</p>
        ) : (
          <div className="space-y-2">
            {(data?.system ?? []).map((t) => (
              <div
                key={t.id}
                className="flex items-center justify-between rounded-lg border border-border bg-muted/30 px-3 py-2.5"
              >
                <div className="flex items-center gap-2.5">
                  <Lock size={12} strokeWidth={1.75} className="shrink-0 text-muted-foreground" />
                  <span className="text-sm font-medium">{t.name}</span>
                  <span className="rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">
                    {t.style_category}
                  </span>
                </div>
                <div className="flex items-center gap-2 text-[11px] text-muted-foreground">
                  {t.usage_count > 0 && <span>{t.usage_count} uses</span>}
                  {t.avg_rating != null && <span>★ {t.avg_rating.toFixed(1)}</span>}
                </div>
              </div>
            ))}
            {(data?.system ?? []).length === 0 && (
              <p className="text-xs text-muted-foreground">No system templates available.</p>
            )}
          </div>
        )}
      </div>

      {/* Custom templates */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-sm font-medium">Custom templates</h3>
            <p className="text-xs text-muted-foreground">
              Studio-specific prompt templates. These override system templates for matching styles.
            </p>
          </div>
          <Button size="sm" variant="outline" onClick={openCreate}>
            <Plus className="mr-1.5 h-3.5 w-3.5" />
            Add template
          </Button>
        </div>

        {isLoading ? (
          <div className="space-y-2">
            {[1, 2].map((i) => <Skeleton key={i} className="h-12 w-full rounded-lg" />)}
          </div>
        ) : (
          <div className="space-y-2">
            {(data?.custom ?? []).map((t) => (
              <div
                key={t.id}
                className="flex items-center justify-between rounded-lg border border-border bg-card px-3 py-2.5"
              >
                <div className="flex items-center gap-2.5">
                  <span className="text-sm font-medium">{t.name}</span>
                  <span className="rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">
                    {t.style_category}
                  </span>
                  {!t.is_active && (
                    <span className="rounded-full bg-muted px-1.5 py-0.5 text-[10px] text-muted-foreground">
                      Inactive
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-1">
                  <Button size="icon" variant="ghost" className="h-6 w-6" onClick={() => openEdit(t)}>
                    <Pencil size={12} />
                    <span className="sr-only">Edit</span>
                  </Button>
                  <Button
                    size="icon"
                    variant="ghost"
                    className="h-6 w-6 text-destructive hover:text-destructive"
                    onClick={() => setDeleteTarget(t)}
                  >
                    <Trash2 size={12} />
                    <span className="sr-only">Delete</span>
                  </Button>
                </div>
              </div>
            ))}
            {(data?.custom ?? []).length === 0 && (
              <div className="rounded-lg border border-dashed border-border p-6 text-center">
                <p className="text-xs text-muted-foreground">
                  No custom templates yet. Create one to customise how AI generates moodboards for specific styles.
                </p>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Create / Edit dialog */}
      <Dialog
        open={isFormOpen}
        onOpenChange={(o) => { if (!o) { setCreateOpen(false); setEditTarget(null) } }}
      >
        <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl">
          <DialogHeader>
            <DialogTitle className="text-sm font-semibold">
              {editTarget ? `Edit template — ${editTarget.name}` : 'New prompt template'}
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-4 py-2">
            {/* Placeholder reference */}
            <div className="rounded-lg bg-muted/40 p-3">
              <p className="mb-2 text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
                Available placeholders
              </p>
              <div className="flex flex-wrap gap-2">
                {PLACEHOLDERS.map((p) => (
                  <span
                    key={p.token}
                    title={p.hint}
                    className="rounded bg-background px-1.5 py-0.5 font-mono text-[11px] text-foreground border border-border"
                  >
                    {p.token}
                  </span>
                ))}
              </div>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-1.5">
                <Label className="text-xs">Name <span className="text-destructive">*</span></Label>
                <Input
                  value={form.name}
                  onChange={(e) => setField('name', e.target.value)}
                  placeholder="e.g. Blackwork — dark themes"
                  className="text-sm"
                />
                {formErrors.name && (
                  <p className="text-xs text-destructive">{formErrors.name}</p>
                )}
              </div>

              <div className="space-y-1.5">
