                ) : <span />}
                <span className="text-[10px] text-muted-foreground">{form.user_prompt_template.length}/4000</span>
              </div>
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs">Image prompt template (optional)</Label>
              <Textarea
                rows={3}
                value={form.image_prompt_template ?? ''}
                onChange={(e) => setField('image_prompt_template', e.target.value)}
                placeholder="A {style} tattoo design, {description}, ultra-detailed, black ink..."
                className="resize-none font-mono text-xs"
                maxLength={2000}
              />
              <p className="text-[11px] text-muted-foreground">
                Leave empty to use the AI-generated image prompt from the moodboard analysis.
              </p>
            </div>
          </div>

          <DialogFooter>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => { setCreateOpen(false); setEditTarget(null) }}
              disabled={isPending}
            >
              Cancel
            </Button>
            <Button size="sm" onClick={handleSave} disabled={isPending}>
              {isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
              {editTarget ? 'Save changes' : 'Create template'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete confirmation */}
      <AlertDialog open={!!deleteTarget} onOpenChange={(o) => { if (!o) setDeleteTarget(null) }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete template?</AlertDialogTitle>
            <AlertDialogDescription>
              &ldquo;{deleteTarget?.name}&rdquo; will be deactivated. Requests that have already used this template
              are not affected.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={handleDelete}
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

