export const metadata: Metadata = {
  title: 'Design Request — InkOS',
}

export default async function AiDesignDetailPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = await params

  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()

  if (!member) redirect('/onboarding')

  return (
    <RequestDetailView requestId={id} studioId={member.studio_id} />
  )
}

import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { ShareDesignPage } from '@/components/ai/ShareDesignPage'

export const metadata: Metadata = {
  title: 'Design Concept',
}

interface SharePayload {
  studioName: string
  studioLogoUrl: string | null
  brandColor: string | null
  styleCategory: string
  bodyArea: string | null
  description: string
  imageUrl: string | null
  signedAt: string
}

async function fetchSharedDesign(token: string): Promise<SharePayload | null> {
  // Build the full URL — must be absolute for server-side fetch
  const baseUrl =
    process.env.NEXT_PUBLIC_APP_URL ??
    (process.env.RAILWAY_STATIC_URL
      ? `https://${process.env.RAILWAY_STATIC_URL}`
      : 'http://localhost:3000')

  const res = await fetch(
    `${baseUrl}/api/public/ai/shared/${encodeURIComponent(token)}`,
    { next: { revalidate: 0 } }, // no caching — signed URL has 1h expiry
  )

  if (res.status === 404) return null
  if (!res.ok) return null

  return res.json() as Promise<SharePayload>
}

export default async function SharedDesignPage({
  params,
}: {
  params: Promise<{ token: string }>
}) {
  const { token } = await params
  const data = await fetchSharedDesign(token)

  if (!data) notFound()

  return <ShareDesignPage data={data} />
}

