'use client'

import { useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import type { AiPlatformUsageSummary } from '@/lib/supabase/types'

type Range = '7d' | '30d' | '90d'

function getDateRange(range: Range): { from: string; to: string } {
  const to = new Date()
  const from = new Date()
  const days = range === '7d' ? 7 : range === '30d' ? 30 : 90
  from.setDate(from.getDate() - days)
  return {
    from: from.toISOString().split('T')[0]!,
    to: to.toISOString().split('T')[0]!,
  }
}

async function fetchPlatformUsage(range: Range): Promise<AiPlatformUsageSummary> {
  const { from, to } = getDateRange(range)
  const res = await fetch(`/api/admin/ai-usage?from=${from}&to=${to}`)
  if (!res.ok) throw new Error('Failed to load platform AI usage')
  return res.json() as Promise<AiPlatformUsageSummary>
}

function centsToDollars(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`
}

export function AdminAiUsageDashboard() {
  const [range, setRange] = useState<Range>('30d')

  const { data, isLoading, isError } = useQuery({
    queryKey: ['admin-ai-usage', range],
    queryFn: () => fetchPlatformUsage(range),
    staleTime: 300_000, // 5 min
  })

  return (
    <div className="space-y-6 p-6">
      <div className="flex items-center justify-between gap-4">
        <div>
          <h1 className="text-xl font-semibold tracking-tight">AI Usage</h1>
          <p className="mt-0.5 text-sm text-muted-foreground">
            Platform-wide AI generation costs and usage.
          </p>
        </div>
        <Select value={range} onValueChange={(v) => setRange(v as Range)}>
          <SelectTrigger className="h-8 w-28 text-xs">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="7d" className="text-xs">Last 7 days</SelectItem>
            <SelectItem value="30d" className="text-xs">Last 30 days</SelectItem>
            <SelectItem value="90d" className="text-xs">Last 90 days</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {isLoading ? (
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
            {[1, 2, 3, 4].map((i) => <Skeleton key={i} className="h-20 rounded-xl" />)}
          </div>
          <Skeleton className="h-64 rounded-xl" />
        </div>
      ) : isError || !data ? (
        <div className="rounded-xl border border-destructive/20 bg-destructive/5 p-6 text-center">
          <p className="text-sm text-destructive">Failed to load platform AI usage data.</p>
        </div>
      ) : (
        <div className="space-y-6">
          {/* Summary KPIs */}
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
            <StatCard label="Total requests" value={data.total_requests.toLocaleString()} />
            <StatCard label="Total outputs" value={data.total_outputs.toLocaleString()} />
            <StatCard label="Total tokens" value={(data.total_tokens / 1000).toFixed(1) + 'K'} />
            <StatCard label="Total cost" value={centsToDollars(data.total_cost_cents)} highlight />
          </div>

          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
            <StatCard
              label="Active studios"
              value={data.total_studios_active.toLocaleString()}
            />
          </div>

          {/* Top studios */}
          {data.top_studios.length > 0 && (
            <div className="rounded-xl border border-border bg-card shadow-card">
              <div className="border-b border-border px-4 py-3">
                <h2 className="text-sm font-medium">Top studios by cost</h2>
              </div>
              <div className="divide-y divide-border">
                {data.top_studios.map((s, idx) => (
                  <div key={s.studio_id} className="flex items-center justify-between px-4 py-2.5">
                    <div className="flex items-center gap-3">
                      <span className="w-5 text-xs font-medium text-muted-foreground">
                        {idx + 1}
                      </span>
                      <span className="text-sm font-medium">{s.name}</span>
                    </div>
                    <div className="flex items-center gap-4 text-xs text-muted-foreground">
                      <span>{s.requests.toLocaleString()} requests</span>
                      <span className="font-medium text-foreground">
                        {centsToDollars(s.cost_cents)}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* By model */}
          {Object.keys(data.by_model).length > 0 && (
            <div className="rounded-xl border border-border bg-card shadow-card">
              <div className="border-b border-border px-4 py-3">
                <h2 className="text-sm font-medium">Breakdown by model</h2>
              </div>
              <div className="divide-y divide-border">
                {Object.entries(data.by_model).map(([model, stats]) => (
                  <div key={model} className="flex items-center justify-between px-4 py-2.5">
                    <span className="font-mono text-xs text-foreground">{model}</span>
                    <div className="flex items-center gap-4 text-xs text-muted-foreground">
                      <span>{stats.calls.toLocaleString()} calls</span>
                      <span>{(stats.tokens / 1000).toFixed(1)}K tokens</span>
                      <span className="font-medium text-foreground">
                        {centsToDollars(stats.cost_cents)}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* By provider */}
          {Object.keys(data.by_provider).length > 0 && (
            <div className="rounded-xl border border-border bg-card shadow-card">
              <div className="border-b border-border px-4 py-3">
                <h2 className="text-sm font-medium">Breakdown by provider</h2>
              </div>
              <div className="divide-y divide-border">
                {Object.entries(data.by_provider).map(([provider, stats]) => (
                  <div key={provider} className="flex items-center justify-between px-4 py-2.5">
                    <span className="text-sm font-medium capitalize">{provider}</span>
                    <div className="flex items-center gap-4 text-xs text-muted-foreground">
                      <span>{stats.calls.toLocaleString()} calls</span>
                      <span className="font-medium text-foreground">
                        {centsToDollars(stats.cost_cents)}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Daily breakdown */}
          {data.daily_breakdown.length > 0 && (
            <div className="rounded-xl border border-border bg-card shadow-card">
              <div className="border-b border-border px-4 py-3">
                <h2 className="text-sm font-medium">Daily breakdown</h2>
              </div>
              <div className="max-h-72 divide-y divide-border overflow-y-auto">
                {[...data.daily_breakdown].reverse().map((day) => (
                  <div key={day.date} className="flex items-center justify-between px-4 py-2.5">
                    <span className="text-xs text-muted-foreground">
                      {new Date(day.date).toLocaleDateString('en-US', {
                        weekday: 'short', month: 'short', day: 'numeric',
                      })}
                    </span>
                    <div className="flex items-center gap-4 text-xs text-muted-foreground">
                      <span>{day.requests} requests</span>
                      <span>{day.outputs} outputs</span>
                      <span className="font-medium text-foreground">
                        {centsToDollars(day.cost_cents)}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

function StatCard({
  label,
  value,
  highlight,
}: {
  label: string
  value: string
  highlight?: boolean
}) {
  return (
    <div className="rounded-xl border border-border bg-card p-4 shadow-card">
      <p className="text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
        {label}
      </p>
      <p
        className={[
          'mt-1.5 text-2xl font-semibold tracking-tight',
          highlight ? 'text-primary' : 'text-foreground',
        ].join(' ')}
      >
        {value}
      </p>
    </div>
  )
}

