/**
 * GET  /api/ai/templates  — list templates (system + studio-custom)
 * POST /api/ai/templates  — create studio-custom template
 */

import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

const STYLE_CATEGORIES = [
  'blackwork', 'watercolor', 'traditional', 'neo_trad', 'realism',
  'geometric', 'minimalist', 'japanese', 'tribal', 'trash_polka',
  'dotwork', 'illustrative', 'abstract', 'lettering', 'other',
] as const

const CreateTemplateSchema = z.object({
  name: z.string().min(1).max(100),
  style_category: z.enum(STYLE_CATEGORIES),
  system_prompt: z.string().min(1).max(8000),
  user_prompt_template: z.string().min(1).max(4000),
  image_prompt_template: z.string().max(2000).nullable().optional(),
  is_default: z.boolean().default(false),
})

async function getStudioId(supabase: Awaited<ReturnType<typeof createClient>>, userId: string): Promise<string | null> {
  const { data } = await supabase
    .from('studio_members')
    .select('studio_id')
    .eq('user_id', userId)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  return data?.studio_id ?? null
}

export async function GET(_req: NextRequest) {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const studioId = await getStudioId(supabase, user.id)
  if (!studioId) return Response.json({ error: 'Studio not found' }, { status: 404 })

  // System templates (studio_id IS NULL) + studio-custom
  const [systemResult, customResult] = await Promise.all([
    supabase
      .from('ai_design_templates')
      .select('*')
      .is('studio_id', null)
      .eq('is_active', true)
      .order('name', { ascending: true }),
    supabase
      .from('ai_design_templates')
      .select('*')
      .eq('studio_id', studioId)
      .eq('is_active', true)
      .order('name', { ascending: true }),
  ])

  if (systemResult.error) {
    logger.error({ err: systemResult.error }, 'failed to fetch system ai_design_templates')
    return Response.json({ error: 'Failed to load templates' }, { status: 500 })
  }

  return Response.json({
    system: systemResult.data ?? [],
    custom: customResult.data ?? [],
  })
}

export async function POST(req: NextRequest) {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const studioId = await getStudioId(supabase, user.id)
  if (!studioId) return Response.json({ error: 'Studio not found' }, { status: 404 })

  const body = CreateTemplateSchema.safeParse(await req.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  // Only owner/admin can create templates
  const { data: member } = await supabase
    .from('studio_members')
    .select('role')
    .eq('studio_id', studioId)
    .eq('user_id', user.id)
    .single()

  if (!member || !['owner', 'admin'].includes(member.role)) {
    return Response.json({ error: 'Forbidden: only owners and admins can create templates' }, { status: 403 })
  }

  const { image_prompt_template, ...rest } = body.data
  const insertData = {
    ...rest,
    studio_id: studioId,
    image_prompt_template: image_prompt_template ?? null,
  }

  const { data, error } = await supabase
    .from('ai_design_templates')
    .insert(insertData)
    .select()
    .single()

  if (error) {
    logger.error({ err: error }, 'failed to create ai_design_template')
    return Response.json({ error: 'Failed to create template' }, { status: 500 })
  }

  return Response.json({ data }, { status: 201 })
}

