import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { ShareDesignPage } from '@/components/ai/ShareDesignPage'

export const metadata: Metadata = {
  title: 'Design Concept',
}

interface ApiShareResponse {
  data: {
    id: string
    image_url: string | null
    created_at: string
    request: {
      style_category: string
      body_area: string | null
      description: string
    } | null
    studio: {
      name: string
      logo_url: string | null
      brand_color: string | null
    } | null
  }
}

async function fetchSharedDesign(token: string): Promise<ApiShareResponse['data'] | null> {
  const baseUrl =
    process.env.NEXT_PUBLIC_APP_URL ??
    (process.env.RAILWAY_STATIC_URL
      ? `https://${process.env.RAILWAY_STATIC_URL}`
      : 'http://localhost:3000')

  const res = await fetch(
    `${baseUrl}/api/public/ai/shared/${encodeURIComponent(token)}`,
    { cache: 'no-store' },
  )

  if (res.status === 404) return null
  if (!res.ok) return null

  const json = await res.json() as ApiShareResponse
  return json.data ?? null
}

export default async function SharedDesignPage({
  params,
}: {
  params: Promise<{ token: string }>
}) {
  const { token } = await params
  const raw = await fetchSharedDesign(token)

  if (!raw || !raw.request) notFound()

  return (
    <ShareDesignPage
      data={{
        studioName: raw.studio?.name ?? 'Studio',
        studioLogoUrl: raw.studio?.logo_url ?? null,
        brandColor: raw.studio?.brand_color ?? null,
        styleCategory: raw.request.style_category,
        bodyArea: raw.request.body_area,
        description: raw.request.description,
        imageUrl: raw.image_url,
        signedAt: raw.created_at,
      }}
    />
  )
}

